<?php require '_layout.php';$db=db();ahead('Products','products.php');$q=trim($_GET['q']??'');$low=isset($_GET['low']);$pg=max(1,(int)($_GET['p']??1));$w=['1=1'];$a=[];
if($q!==''){$w[]='(p.name LIKE ? OR p.sku LIKE ?)';array_push($a,"%$q%","%$q%");}if($low)$w[]='p.stock<=5';
$c=$db->prepare('SELECT COUNT(*) FROM products p WHERE '.implode(' AND ',$w));$c->execute($a);$tot=$c->fetchColumn();
$st=$db->prepare('SELECT p.*,s.name sub FROM products p JOIN categories s ON s.id=p.category_id WHERE '.implode(' AND ',$w).' ORDER BY p.name LIMIT 50 OFFSET '.(($pg-1)*50));$st->execute($a);?>
<?=isset($_GET['saved'])?'<p class="okm">Product saved</p>':''?><form class="flt"><input name="q" value="<?=e($q)?>" placeholder="Search name or SKU"><label><input type="checkbox" name="low" <?=$low?'checked':''?> onchange="this.form.submit()"> Low stock only</label><button class="btn">Search</button><a class="btn ghost" href="product.php">+ Add product</a></form>
<table class="tb"><tr><th></th><th>SKU</th><th>Name</th><th>Aisle</th><th>Price</th><th>Stock</th><th>Status</th></tr><?php foreach($st as $r): ?><tr><td><?php $im=product_images($r['sku']);echo $im?'<img class="th2" src="../'.e($im[0]).'" alt="">':'<span class="th2 nop">&ndash;</span>'; ?></td><td><?=e($r['sku'])?></td><td><a href="product.php?sku=<?=e($r['sku'])?>"><?=e($r['name'])?></a><?=!empty($r['featured'])?' <span title="Featured" style="color:#d98f00">&#9733;</span>':''?></td><td><?=e($r['sub'])?></td><td><?=money($r['base_price'])?><small> <?=$r['sold_by_type']=='variant'?'from':'/'.e($r['unit_label'])?></small></td><td class="<?=$r['stock']<=5?'bad':''?>"><?=$r['stock']?></td><td><?=badge($r['status']=='active'?'completed':'cancelled',$r['status']=='active'?'Live':'Hidden')?></td></tr><?php endforeach; ?></table>
<p class="np"><?=$tot?> products. <?php if($pg>1): ?><a href="?<?=http_build_query(['q'=>$q,'p'=>$pg-1])?>">&larr; Prev</a> <?php endif; if($pg*50<$tot): ?><a href="?<?=http_build_query(['q'=>$q,'p'=>$pg+1])?>">Next &rarr;</a><?php endif; ?></p><?php afoot();
